/**
 * @fileoverview A nunber of functions to assist in the displaying of overlays on the screen
 * @category Utility
 * @description Various overlay rendering functions
 */
import { useState, useRef, useEffect } from "react";
import { useTrail, animated, useSpring } from "@react-spring/web";
import { useNavigate } from "react-router-dom";
import { useProgress } from "@react-three/drei";

/**
 * Allows for a loading screen at the start of a page that waits for the assets to load
 * @function
 * @category Loading
 */
function Loader() {
  /**
   * Variable that tracks the current progress on asset loading on the page
   * @type {useProgress}
   */
  const { progress } = useProgress();

  return (
    /* The white background */
    <div
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        width: "100vw",
        height: "100vh",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        background: "#fff",
        zIndex: 2000,
        color: "black",
        fontFamily: "sans-serif",
      }}
    >
      {/* The "Loading Experience" prompt for the user */}
      <div
        style={{
          fontSize: "2rem",
          marginBottom: "20px",
          letterSpacing: "0.2em",
        }}
      >
        LOADING EXPERIENCE
      </div>

      {/* A % bar that tracks and displays the current load progress */}
      <div style={{ width: "200px", height: "2px", background: "#333" }}>
        <div
          style={{
            width: `${progress}%`,
            height: "100%",
            background: "#6a0dad",
            transition: "width 0.3s ease",
          }}
        />
      </div>

      {/* The numerical display of the load % */}
      <div style={{ marginTop: "10px", fontSize: "0.8rem", opacity: 0.5 }}>
        {Math.round(progress)}%
      </div>
    </div>
  );
}

/**
 * Allows for a custom start screen with a button to start the experience; assets load on click and the page is not revealed until assets fully loaded
 * @function
 * @category Loading
 * @deprecated use Loader() instead
 */
function StartScreen({ onStart, visible }) {
  const styles = useSpring({
    opacity: visible ? 1 : 0,
    pointerEvents: visible ? "auto" : "none",
    config: { duration: 500 },
  });

  return (
    <animated.div
      style={{
        ...styles,
        position: "absolute",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        backgroundColor: "black",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        zIndex: 20,
      }}
    >
      <button
        id="startButton"
        style={{
          padding: "20px 40px",
          fontSize: "42px",
          fontWeight: "bold",
          borderRadius: "12px",

          fontFamily: "Orbitron, sans-serif",
        }}
        onClick={onStart}
      >
        By MOBOLAJI ADEWALE
      </button>

      <div
        id="hintText"
        style={{
          position: "absolute",
          bottom: "2%",
          padding: "20px 40px",
          fontSize: "15px",
          borderRadius: "1px",
          color: "white",
          fontFamily: "Orbitron, sans-serif",
        }}
      >
        HINT: Find the glowing orbs and press them to learn more about me
      </div>
    </animated.div>
  );
}

/**
 * Displays a html/css overlay over the 3D scene; that is populated with JSON data as text; includes a return to scene and internal navigation buttons
 * @function
 * @category Overlay
 */
function Overlay({ isActive, onClose, items = [] }) {
  /**
   * Allows for internal navigation of the page
   * @type {useNavigate}
   */
  const navigate = useNavigate();

  /**
   * Fades in and out the overlay
   * @type {useSpring}
   */
  const overlaySpring = useSpring({
    opacity: isActive ? 1 : 0,
    config: { tension: 220, friction: 50 },
  });

  /**
   * Allows for animations in sequence of a list/array of elements - applies a CSS animation transform to have the different elements slide in from the right of the screen and slide back out later
   * @type {useTrail}
   */
  const trail = useTrail(Array.isArray(items) ? items.length : 0, {
    from: { transform: "translateX(200%)", opacity: 0 },
    to: {
      transform: isActive ? "translateX(0%)" : "translateX(100%)",
      opacity: isActive ? 1 : 0,
    },
    config: { mass: 1, tension: 150, friction: 100, delay: 100 },
  });

  return (
    //Animated element that allows for the useSpring and useTrail to work
    <animated.div
      className="jsonOverlay"
      style={{
        pointerEvents: isActive ? "auto" : "none",
        opacity: overlaySpring.opacity,
      }}
    >
      {/* Exit button for the overlay menu */}
      <div className="normalExitButton" onClick={onClose}>
        Exit
      </div>

      {/* The JSON imported items that slide in from the right */}
      {trail.map((style, index) => {
        const item = items[index];
        //const isExternal = Boolean(item.website);
        //const isNavigable = Boolean(item.navigation);

        return (
          // The individual items pulled from the JSON
          <animated.div
            key={index}
            className="jsonOverlayItems"
            style={{
              transform: style.transform,
            }}
          >
            {/* The TITLE of the item */}
            <h2 style={{ fontSize: "20px", marginBottom: "10px" }}>
              {item.title}
            </h2>
            {!item.WIP && (
              <a
                className="goToComputerButton"
                onClick={
                  // A conditional on whether the JSON of the item has the property EXTERNAL (denoting an external website link)
                  item.external
                    ? // If an external link exists - go to that page
                      () => {
                        window.location.href = item.website;
                      }
                    : // If an internal link is present instead; let the react-router handle the navigation
                      () => {
                        //console.log("HERE");

                        // If a site link is found; pass that page to the IFRAME on the COMPUTER page; to be rendered within the static wordpress site
                        if (item.siteLink) {
                          const fullUrl = `${import.meta.env.BASE_URL}${
                            item.siteLink
                          }index.html`;

                          //console.log("Passing to iframe:", fullUrl);

                          // Passing site link through the COMPUTER page's IFRAME
                          navigate(`/Computer`, {
                            state: { iframeUrl: fullUrl },
                          });
                        } else {
                          //console.log("SHOULD BE MOVING HERE");

                          // Navigate to the page specified
                          navigate(item.internalLink);
                        }
                      }
                }
              >
                Go To
              </a>
            )}{" "}
            {item.WIP && <a className="workInProgressButton">W I P</a>}
            {/* The MAIN BODY text of the item */}
            <p>{item.abstract}</p>
          </animated.div>
        );
      })}
    </animated.div>
  );
}

function AudioButton({ url }) {
  const [playing, setPlaying] = useState(false);
  const audioRef = useRef(null);

  // This effect handles stopping the audio if the component unmounts
  // or if the URL changes (page navigation)
  useEffect(() => {
    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current = null;
      }
    };
  }, [url]);

  const toggleAudio = () => {
    if (!audioRef.current) {
      audioRef.current = new Audio(url);
      audioRef.current.loop = true;
    }

    if (playing) {
      audioRef.current.pause();
    } else {
      audioRef.current
        .play()
        .catch((err) => console.error("Audio blocked:", err));
    }
    setPlaying(!playing);
  };

  return (
    <button
      onClick={toggleAudio}
      className="OverlayButton"
      style={{
        position: "fixed",
        bottom: "20px",
        left: "20px",
        zIndex: 2000, // Above the Canvas and Overlay
        padding: "10px 20px",
        background: "rgba(0, 0, 0, 0.7)",
        color: "white",
        border: "1px solid #6a0dad",
        borderRadius: "2px",
        cursor: "pointer",
        fontFamily: "monospace",
        backdropFilter: "blur(10px)",
        textTransform: "uppercase",
      }}
    >
      {playing ? "🔊 Mute" : "🔈 Play Ambience"}
    </button>
  );
}

function HeadingsButton({ showHeadings, setShowHeadings }) {
  const toggleHeadings = () => {
    // This toggles the boolean to its opposite value
    setShowHeadings((prev) => !prev);
  };

  return (
    <button
      onClick={toggleHeadings}
      className="OverlayButton"
      style={{
        position: "fixed",
        bottom: "20px",
        right: "20px",
        zIndex: 2000,
        padding: "10px 20px",
        background: "rgba(0, 0, 0, 0.7)",
        color: "white",
        border: "1px solid #6a0dad",
        borderRadius: "2px",
        cursor: "pointer",
        fontFamily: "monospace",
        backdropFilter: "blur(10px)",
        textTransform: "uppercase",
      }}
    >
      {showHeadings ? "Hide Headings" : "Show Headings"}
    </button>
  );
}

function ResumeButton() {
  return (
    <a
      className="OverlayButton"
      style={{
        position: "fixed",
        top: "20px",
        right: "20px",
        zIndex: 2000,
        padding: "10px 20px",
        background: "rgba(0, 0, 0, 0.7)",
        color: "white",
        border: "1px solid #6a0dad",
        borderRadius: "2px",
        cursor: "pointer",
        fontFamily: "monospace",
        backdropFilter: "blur(10px)",
        textTransform: "uppercase",
      }}
      href={`${import.meta.env.BASE_URL}Resume.pdf`}
      target="_blank"
      rel="noopener noreferrer"
    >
      Resume
    </a>
  );
}

export {
  StartScreen,
  Overlay,
  Loader,
  AudioButton,
  HeadingsButton,
  ResumeButton,
};
